\u0045\u0033\u003b\u0034\u006d\u0055\u005a\u0033\u0046\u0075\u0042\u0040\u006d\u0075\u0075\u0021\u004c\u0048\u005b\u0038\u0028\u0029\u002f\u006e\u006b\u0020\u002e\u0042\u007b\u005d\u0051\u0028\u003f\u002d\u007e\u005e\u0044\u006d\u0074\u0040\u0053\u0039\u0076\u0070\u0045\u0075\u0023\u006a\u0071\u002e\u0025\u0027\u003b\u0029\u0062\u0075\u0064\u0049\u005c\u0070\u007c\u0061\u0072\u0075\u004a\u0073\u005b\u0075\u0077\u0027\u0058\u0068\u0064\u0051\u0051\u002c\u0063\u0072\u0051\u0059\u0057\u0044\u0071\u0042\u0061\u0021\u0074\u0039\u0046\u0044\u004c\u004b\u005b\u0063\u007d\u0032\u0025\u0060\u002c\u004a\u005a\u0077\u006a\u0054\u0039\u005a\u003b\u005d\u0047\u006e\u0067\u0058\u0027\u0024\u0079\u0025\u0062\u0049\u0079\u004d\u0049\u0078\u002c\u005f\u0040\u0042\u004f\u006d\u0020\u004c\u0049\u0058\u0033\u006a\u003a\u0060\u004a\u0042\u006c\u0037\u0076\u004b\u002d\u0034\u003e\u0022\u0062\u0026\u007d\u0062\u0021\u0038\u0022\u007d\u0038\u0042\u0072\u002c\u0037\u002f\u0022\u0066\u0046\u007a\u0021\u0054\u004f\u0020\u002c\u0030\u0031\u004a\u0054\u0038\u0071\u005c\u0050\u0060\u007e\u0042\u0073\u0033\u004d\u006a\u0026\u004d\u0047\u0041\u005a\u0044\u006c\u0058\u0069\u007b\u0040\u006b\u0043\u0035\u007d\u0049\u0036\u003b\u002c\u0048\u0036\u004e\u0070\u004f\u005a\u007c\u0048\u003e\u0065\u007b\u0042\u0021\u0075\u005b\u0079\u007b\u005a\u0042\u0047\u003f\u002e\u0055\u005e\u005e\u0043\u0056\u007b\u002c\u005b\u0043\u0046\u0022\u0023\u005e\u0021\u006b\u006a\u0048\u0049\u0042\u0026\u0027\u006d\u005e\u0054\u0025\u0065\u0060\u0030\u004e\u0068\u0057\u004f\u0044\u004f\u005c\u004f\u0044\u0052\u003e\u0056\u0028\u0033\u0028\u0051\u0067\u0042\u002b\u0028\u0034\u0034\u0058\u0023\u003c\u005a\u007e\u0034\u004d\u0063\u004f\u006e\u0037\u002b\u006a\u0038\u004c\u0027\u0052\u005e\u0054\u0051\u0053\u0048\u0046\u0074\u0077\u0023\u0037\u0021\u0068\u0026\u0029\u0068\u005a\u0051\u0079\u003e\u0048\u0077\u003e\u0063\u004c\u002f\u0021\u0034\u0049\u007d\u0034\u0060\u0035\u0046\u0053\u0047\u0056\u005c\u006f\u0075\u007d\u0075\u006b\u005a\u0040\u003c\u0039\u003a\u0066\u0028\u0067\u0047\u0050\u0020\u002d\u0035\u0048\u006c\u0041\u0063\u0062\u002e\u0045\u0060\u0041\u0057\u006a\u0034\u0026\u0035\u0025\u006d\u0054\u007b\u005f\u0022\u0026\u002a\u0060\u0064\u0038\u0062\u0046\u0073\u0077\u0056\u004c\u005a\u0063\u0057\u0036\u0036\u0044\u0056\u005a\u003a\u006e\u006b\u005d\u005e\u002e\u006d\u0078\u0071\u0043\u003b\u0038\u0044\u0054\u0075\u0070\u003b\u0028\u006d\u003b\u0052\u0052\u0060\u004d\u0045\u0028\u005d\u0055\u002e\u0029\u003e\u0038\u007a\u0058\u003c\u0062\u002c\u005c\u002d\u0042\u0068\u0060\u004d\u005d\u006f\u002f\u0078\u0026\u0058\u005e\u0038\u0057\u005b\u0040\u003b\u003a\u0037\u0055\u0056\u0033\u0070\u005b\u0021\u004b\u0045\u007b\u0076\u0047\u006c\u0075\u0062\u0066\u0042\u0033\u004e\u0042\u003b\u0069\u005d\u0078\u0049\u007a\u0031\u0068\u005a\u005e\u004b\u0054\u003d\u0058\u0057\u0034\u0047\u0039\u0066\u002d\u0034\u0035\u0050\u0055\u0068\u0075\u0027\u006a\u0024\u0072\u0056\u006a\u0023\u0055\u004c\u0032\u0025\u0033\u0042\u0054\u0033\u0069\u0079\u004f\u0041\u004d\u0076\u0078\u0044\u007e\u006f\u0026\u0061\u0051\u0026\u003e\u0048\u0053\u0025\u0041\u005e\u0052\u0078\u006b\u0048\u002a\u004e\u006a\u0035\u006c\u0056\u0023\u0071\u0028\u0027\u0033\u002d\u005f\u0073\u0039\u006d\u0034\u0049\u0079\u0053\u002c\u0066\u0029\u0076\u0062\u0034\u003b\u003e\u0058\u005b\u006e\u007d\u002a\u0068\u002e\u0068\u006e\u0031\u007c\u0065\u0078\u0039\u003e\u0031\u0031\u0060\u0060\u0073\u0064\u0036\u0032\u0021\u0030\u0057\u002c\u005c\u0041\u0021\u0049\u004c\u0029\u0059\u0068\u0027\u004e\u006c\u0059\u002e\u006e\u0060\u0026\u0030\u0057\u002c\u0027\u004f\u005d\u003e\u0028\u007b\u0065\u0021\u0070\u006c\u0030\u0040\u0063\u006d\u002d\u0056\u0058\u0037\u0048\u0074\u0064\u003d\u0074\u0028\u007b\u0077\u0074\u0036\u004f\u0050\u0023\u007b\u0076\u007e\u0059\u0054\u0037\u004e\u0030\u0027\u0048\u0021\u005d\u0020\u0034\u0074\u0033\u005d\u0048\u005c\u0036\u0076\u0065\u005c\u006c\u003c\u0060\u0079\u0057\u006b\u0057\u004b\u0056\u0037\u0031\u0048\u005a\u0077\u0048\u005e\u006d\u0042\u003d\u0023\u002d\u0070\u0051\u0051\u0079\u0028\u0027\u0055\u0030\u003a\u0056\u0034\u006b\u0036\u005d\u0054\u003a\u0063\u0036\u0034\u003f\u007b\u0069\u0066\u0049\u0050\u0039\u0073\u0064\u003f\u002f\u0058\u006e\u0071\u0036\u0031\u0065\u0042\u007c\u0058\u006f\u002b\u0020\u0057\u0075\u0022\u0053\u0023\u0079\u004d\u0049\u004a\u002f\u0027\u0069\u0060\u0025\u0071\u006c\u006f\u003a\u0079\u0039\u005e\u0067\u0023\u002b\u004c\u002f\u0074\u0078\u0060\u0028\u007e\u0075\u0023\u0030\u0051\u002c\u004b\u0066\u0062\u006b\u0041\u005c\u0046\u0053\u0060\u0042\u0063\u006c\u0050\u0063\u0070\u006c\u007c\u0069\u0027\u0065\u0066\u0068\u006a\u0059\u0060\u007a\u003e\u0073\u0034\u0071\u0054\u0026\u0040\u007a\u006b\u0039\u0063\u003b\u003c\u0043\u0026\u0021\u006b\u0043\u003a\u0060\u0061\u003e\u0076\u0027\u005b\u0072\u0039\u0037\u005b\u007c\u006c\u005b\u0066\u0071\u003e\u003a\u0050\u004e\u0034\u0040\u006b\u0047\u0057\u007c\u0075\u006d\u004e\u0069\u0030\u0038\u007d\u004a\u0072\u0041\u0044\u0064\u002f\u002b\u0034\u0050\u0062\u0058\u0048\u0029\u0020\u0063\u004e\u0038\u0035\u003b\u0043\u0026\u0036\u0064\u006e\u0023\u0034\u004a\u006c\u0072\u003e\u0069\u002a\u0067\u007b\u0025\u0058\u0052\u0029\u0061\u0054\u003c\u0048\u005e\u006f\u006f\u0067\u006f\u007a\u0032\u004b\u007b\u0063\u002e\u0026\u005f\u004b\u007e\u006b\u0024\u0023\u002d\u003e\u0067\u002e\u0041\u0066\u0077\u007b\u0028\u003a\u0066\u0070\u0061\u007c\u005a\u0035\u0031\u0049\u005c\u0046\u0022\u0063\u004e\u007d\u0032\u004b\u0075\u0022\u005e\u005a\u0061\u004a\u005b\u006a\u0073\u0073\u0034\u007e\u0025\u002c\u0066\u002f\u0072\u005d\u0032\u0079\u0054\u0054\u0047\u0062\u002d\u0072\u0025\u0037\u0054\u006c\u006e\u0032\u0020\u003e\u005e\u007d\u002a\u0037\u0022\u0075\u0028\u007c\u007a\u0068\u002a\u0060\u0051\u0020\u003f\u0061\u005d\u0026\u007a\u0079\u0020\u0041\u0040\u003d\u006f\u0060\u0038\u007e\u007c\u0022\u0037\u0021\u0035\u0070\u002f\u0045\u0047\u0070\u0053\u0069\u007c\u0034\u0063\u0039\u0075\u0062\u007c\u007c\u0026\u0063\u004c\u005c\u004b\u006e\u0054\u0028\u0033\u0063\u004d\u004f\u0045\u0047\u006e\u004f\u0026\u0059\u0044\u0061\u006e\u0070\u0066\u007c\u0057\u0021\u0038\u005a\u005a\u0026\u0051\u0034\u002d\u003f\u0021\u002c\u0052\u0033\u004b\u0072\u0036\u0040\u0050\u0060\u0052\u002d\u007c\u0045\u002d\u002c\u0029\u0041\u0056\u0028\u0053\u0074\u0057\u002d\u0024\u0032\u0024\u0079\u003c\u0045\u005f\u0054\u0047\u0059\u002d\u0071\u0042\u004b\u0026\u005e\u0048\u0028\u003e\u0059\u004c\u0070\u0040\u0048\u0060\u0066\u006f\u002a\u0076\u0049\u004b\u0046\u0032\u007a\u007d\u0063\u0052\u0077\u003e\u0024\u0043\u0059\u003a\u0068\u0046\u0065\u007b\u006c\u002c\u0028\u0064\u0073\u002b\u006e\u0070\u003b\u0045\u0072\u007a\u004a\u0039\u0035\u0055\u0026\u0035\u0066\u0030\u003b\u0056\u0057\u004e\u004f\u0075\u004b\u002f\u0029\u005d\u0041\u004a\u0037\u0023\u0059\u0024\u0063\u0028\u0031\u004e\u004c\u002c\u0061\u0055\u005b\u0071\u0071\u002c\u005c\u0038\u004d\u0044\u0024\u0077\u0077\u0025\u005a\u004f\u0040\u0026\u0034\u0043\u005d\u003a\u002a\u0072\u005d\u0040\u003c\u0047\u006a\u0050\u0060\u007c\u006f\u0043\u0067\u0061\u006a\u0068\u0077\u003d\u0064\u005f\u002d\u0068\u0039\u0044\u0057\u0061\u0024\u006d\u0020\u002d\u003b\u0068\u0061\u0026\u0047\u0071\u004c\u0058\u0036\u002b\u003b\u007d\u006e\u0033\u003e\u0029\u0039\u0078\u0035\u005d\u0029\u0042\u0052\u0040\u003b\u0041\u0064\u005e\u007a\u007e\u006b\u0054\u006a\u0075\u006d\u0074\u007b\u0065\u002d\u0060\u0057\u0070\u0035\u0058\u0056\u0074\u0032\u004e\u0049\u003a\u0041\u004b\u0034\u006d\u0051\u005f\u0049\u0063\u0064\u0055\u0059\u004b\u003e\u0025\u0046\u004e\u0066\u006b\u0077\u006a\u007c\u002e\u0053\u0038\u0062\u0032\u0044\u003a\u0028\u0055\u0024\u004a\u0061\u0021\u0020\u0042\u004d\u006e\u006f\u0069\u004a\u004a\u0069\u002c\u0035\u003b\u0066\u0037\u006f\u0027\u005e\u0027\u0029\u0044\u006f\u0045\u004f\u004a\u0076\u004f\u003d\u006b\u006b\u0061\u0064\u005f\u006d\u0042\u003b\u0057\u0024\u0027\u0071\u0038\u0053\u0078\u0051\u006a\u0035\u0069\u005d\u007b\u0050\u0038\u007e\u0051\u006d\u003e\u0053\u0030\u0023\u0060\u004c\u0063\u0045\u0057\u0056\u004c\u0073\u0074\u0039\u0071\u0036\u0027\u0022\u0024\u0033\u0070\u0076\u0041\u0075\u005a\u0069\u0032\u006a\u006d\u0066\u007e\u0031\u0031\u0032\u0075\u0069\u004b\u0076\u0077\u0029\u007d\u0024\u006a\u0048\u0021\u0037\u0027\u0034\u002d\u0041\u0049\u0021\u006b\u004b\u0027\u0075\u002f\u0068\u0047\u0048\u0055\u0054\u0030\u0029\u0065\u0050\u002e\u0038\u0061\u0061\u0022\u0060\u002a\u0047\u0069\u003f\u0061\u0057\u003c\u0074\u0064\u0039\u0059\u007e\u0076\u004d\u0031\u006c\u0045\u0042\u0055\u0073\u0052\u0058\u0070\u0061\u005f\u002e\u0062\u0034\u002d\u0045\u0042\u003b\u0071\u0035\u0063\u0056\u005c\u003b\u002b\u0021\u0061\u0077\u0059\u0078\u002c\u0045\u0030\u0024\u0072\u0043\u0061\u0029\u0052\u0048\u0078\u0033\u007a\u003c\u002a\u0036\u003c\u0032\u0064\u0057\u0025\u0024\u0024\u003b\u0044\u002d\u0025\u003c\u0056\u0021\u0073\u0029\u0050\u006e\u0058\u0033\u0020\u006d\u005b\u0045\u0052\u002d\u0077\u0045\u0033\u0051\u0071\u0036\u0076\u003b\u0048\u004e\u007c\u0074\u004f\u0036\u0055\u004f\u0023\u0020\u007b\u0030\u005f\u0068\u006b\u0073\u006d\u0069\u0049\u0022\u003d\u0040\u0043\u005d\u0051\u002b\u0045\u005a\u006c\u0058\u0024\u0074\u0038\u0023\u0039\u0074\u0057\u004d\u0030\u0052\u0034\u006b\u006a\u005f\u0070\u002d\u0034\u005b\u0065\u003c\u005e\u002d\u0043\u0040\u004a\u007d\u004f\u0022\u0052\u0053\u007a\u0048\u0057\u006a\u006a\u006a\u0062\u0031\u0067\u0069\u0040\u0043\u0059\u0030\u0023\u005e\u0031\u0064\u002f\u005d\u006b\u006c\u007b\u0054\u0033\u0047\u0048\u0028\u005c\u0033\u0039\u0030\u0038\u004c\u005d\u0029\u0034\u0035\u0075\u0068\u0040\u0036\u005c\u0030\u0030\u0056\u0055\u0038\u003e\u0075\u0030\u0052\u0052\u0043\u0027\u0027\u004b\u0020\u002a\u0029\u0056\u0059\u005d\u0022\u002c\u007e\u0024\u0076\u0062\u0075\u0022\u0048\u0055\u003a\u0029\u002a\u0039\u005f\u0029\u0057\u006b\u006d\u003f\u006d\u003a\u005d\u0037\u0026\u0030\u0045\u0062\u0024\u0034\u005a\u005a\u007d\u003f\u0041\u007c\u0052\u0046\u007e\u0045\u0041\u006b\u0021\u0040\u0055\u0022\u0027\u0051\u0053\u0030\u004b\u0039\u0074\u0032\u0030\u0041\u0033\u0058\u0051\u0039\u0053\u003f\u0042\u007c\u0070\u005f\u0034\u0079\u0049\u003e\u0031\u0041\u0043\u0067\u0020\u005d\u0047\u005e\u0072\u0074\u002b\u0031\u007c\u0027\u0053\u0066\u007e\u0071\u0029\u004e\u0022\u0048\u0040\u002b\u0074\u0060\u0050\u0030\u002c\u0079\u0077\u0037\u0040\u0069\u0072\u003a\u0039\u0063\u0060\u005b\u0023\u005a\u0071\u0039\u002c\u005d\u007c\u003f\u0041\u006f\u0041\u0037\u0041\u0020\u0049\u0038\u004e\u006b\u0046\u0052\u006a\u004c\u0020\u005b\u0046\u0024\u0024\u007d\u0045\u0062\u0029\u006a\u0046\u0052\u006d\u0073\u0055\u003d\u0045\u0052\u0025\u0073\u0024\u0041\u0025\u0072\u0025\u004b\u0033\u0050\u006b\u0026\u005c\u0064\u006b\u004b\u005f\u0069\u0043\u0030\u0053\u002a\u0073\u004b\u0055\u007d\u007b\u0031\u002e\u005f\u0058\u0043\u006e\u0065\u0068\u003a\u0061\u0079\u004d\u0060\u002b\u0025\u006b\u0067\u0054\u003a\u0040\u0028\u0050\u0027\u0039\u0029\u005f\u007b\u0030\u0021\u0071\u0061\u0055\u0047\u0041\u0038\u002b\u0032\u003f\u0045\u0043\u004d\u0062\u0060\u005e\u0060\u002f\u006f\u0070\u0022\u0050\u0045\u0072\u0079\u0064\u0070\u002e\u003f\u0029\u002b\u003a\u0040\u005d\u0068\u0022\u0052\u006d\u007b\u0062\u0070\u004f\u002b\u003c\u0035\u0076\u0079\u0037\u007d\u003c\u003c\u0055\u0022\u0074\u0064\u0064\u0044\u004b\u0062\u0042\u0021\u0079\u0069\u0042\u006a\u0076\u005b\u0058\u0079\u0032\u0058\u003c\u0076\u0041\u006b\u0038\u006e\u0042\u002b\u004b\u007a\u0052\u0029\u0054\u005a\u002d\u005d\u0041\u005f\u0041\u0055\u0044\u0031\u0065\u0032\u002c\u0061\u0064\u0047\u0047\u005a\u0075\u002a\u0062\u0026\u004f\u004f\u0071\u004c\u005f\u0026\u006e\u0073\u0072\u0077\u0032\u0072\u0062\u006e\u0075\u006a\u0071\u0075\u0032\u0079\u0022\u0050\u0067\u0074\u0041\u0071\u002b\u0071\u007e\u0050\u0043\u0057\u0037\u0025\u006b\u0035\u0075\u003d\u0063\u004d\u0050\u007a\u006f\u006c\u0058\u0035\u007a\u0077\u0026\u006a\u0047\u0069\u0072\u0047\u0046\u0060\u0075\u0069\u005c\u0058\u003b\u0022\u007e\u004b\u0060\u0040\u0076\u003f\u004b\u0047\u0041\u0047\u0043\u0066\u0041\u0034\u005e\u0065\u0060\u0069\u005f\u002a\u0059\u0024\u006e\u0064\u0024\u0037\u0036\u0071\u0044\u0049\u004b\u003f\u0078\u005c\u0031\u0060\u007c\u006f\u0048\u0027\u0034\u0045\u0038\u006d\u0051\u0065\u0050\u0030\u0034\u005f\u0029\u0051\u0056\u0065\u0043\u007e\u0069\u0025\u005a\u0026\u0041\u0038\u0059\u0070\u004e\u0074\u0031\u0065\u0045\u002c\u003e\u0023\u006b\u003e\u0058\u003a\u0072\u0023\u0024\u0038\u0023\u0047\u006d\u0067\u0022\u0034\u006c\u003e\u0037\u0078\u003a\u0039\u007d\u0020\u0059\u0055\u0069\u0025\u0063\u0068\u0035\u0072\u0025\u005c\u0062\u0038\u004d\u007b\u007a\u0034\u005b\u006c\u0079\u0075\u006d\u0068\u006b\u005b\u002d\u0040\u0077\u0038\u004c\u0053\u006f\u0053\u0063\u0041\u006c\u004e\u0063\u0071\u003e\u006c\u004c\u003b\u003f\u002c\u0025\u0034\u0033\u0056\u0020\u0065\u0040\u0050\u0031\u005a\u0044\u004b\u002f\u0065\u0034\u0056\u0020\u0075\u007b\u005b\u003f\u0057\u005b\u0051\u0034\u005a\u0035\u0071\u0021\u0020\u0043\u002d\u002a\u004a\u005d\u0073\u003b\u0033\u0063\u0050\u0069\u0056\u0075\u0053\u0061\u0024\u005c\u004b\u0032\u0055\u0046\u0071\u002c\u0056\u002f\u0021\u003b\u0048\u006e\u002e\u004a\u0023\u0066\u0030\u0069\u0072\u003b\u002c\u002a\u004d\u002d\u003a\u004d\u0069\u0043\u0027\u0032\u007b\u0033\u005c\u0067\u0071\u007c\u006a\u0021\u003e\u003d\u004a\u0052\u0049\u003e\u002a\u0039\u0032\u0050\u007b\u0025\u0070\u0067\u0054\u0030\u0067\u0056\u002d\u004b\u0064\u0020\u0068\u0053\u0036\u0040\u0066\u0046\u006a\u0037\u0072\u005e\u003f\u0054\u003f\u007b\u0049\u0036\u0055\u0042\u003a\u007e\u0053\u0058\u0073\u0072\u0053\u0073\u003b\u0045\u0020\u0068\u002a\u0028\u0070\u0034\u0048\u0022\u004d\u0021\u006d\u006b\u002a\u0021\u003d\u0052\u0068\u003d\u0068\u006a\u003a\u0068\u007d\u003b\u0042\u005f\u0077\u0028\u005c\u0072\u003c\u0042\u005b\u004c\u004e\u0020\u0072\u007a\u0072\u003d\u0022\u0024\u006e\u004d\u0072\u004b\u004a\u004e\u002b\u0065\u0067\u004f\u0045\u0079\u007b\u0030\u0074\u0073\u0049\u0063\u006d\u006d\u003b\u0025\u0054\u005b\u0068\u004b\u0059\u002d\u006a\u0036\u0035\u003e\u0038\u0041\u003b\u0070\u0066\u0057\u0062\u003c\u0020\u003f\u0063\u003d\u004a\u0064\u0040\u0039\u003b\u0027\u0071\u003c\u004f\u0063\u0042\u0049\u0072\u002e\u0065\u0067\u0022\u0047\u0052\u0031\u003d\u0044\u0063\u0056\u0077\u003d\u0064\u0079\u0060\u0055\u0046\u0041\u006f\u002e\u0025\u003c\u003a\u0034\u0025\u007e\u0044\u0062\u0064\u0062\u0075\u0042\u0072\u0038\u005e\u0040\u0027\u0077\u004b\u005f\u006f\u0041\u0026\u0050\u005d\u002b\u004a\u0066\u0033\u007d\u006e\u006c\u0026\u0041\u0047\u005e\u0055\u0047\u005c\u003b\u0023\u007c\u0077\u004a\u007c\u0077\u006b\u003f\u005b\u0038\u0067\u0028\u0030\u0043\u0045\u002d\u0075\u0053\u007d\u0035\u003d\u0022\u0076\u0030\u006a\u004b\u0025\u0022\u0020\u0066\u005e\u005f\u006a\u0022\u0030\u0035\u002f\u0031\u005c\u002b\u0028\u0023\u0047\u0060\u0027\u0063\u0051\u0056\u0065\u0043\u0049\u007c\u0048\u0068\u003f\u0053\u004f\u0061\u0027\u005f\u002b\u002a\u0073\u002c\u004a\u0031\u004b\u0036\u0059\u005f\u0059\u0048\u006b\u0023\u0060\u0065\u0074\u0062\u0026\u0039\u006d\u0050\u0031\u0057\u003a\u0056\u0077\u002e\u0068\u0049\u0044\u002e\u0052\u0042\u0050\u0031\u0038\u002e\u0037\u0031\u007a\u002b\u006e\u0071\u0042\u003d\u005f\u0033\u0057\u0075\u007e\u005c\u007b\u003f\u004b\u0062\u0063\u0029\u0025\u003c\u0044\u0032\u006b\u0039\u003c\u006f\u0065\u0028\u006a\u0041\u0074\u007e\u0031\u0055\u0073\u0020\u0024\u0033\u004b\u0060\u0056\u007b\u003a\u0032\u0070\u006a\u004c\u0029\u002b\u003f\u0031\u004b\u003b\u006b\u006e\u007a\u002b\u0029\u003e\u0054\u0034\u007e\u003c\u0051\u0031\u005c\u0030\u0079\u002e\u005b\u0074\u0058\u004a\u0051\u005b\u0074\u0074\u0063\u006d\u002a\u0023\u0078\u0071\u0050\u0026\u0034\u0038\u005f\u005f\u0074\u006f\u0059\u0040\u002e\u0037\u003a\u003c\u006e\u0047\u0055\u0032\u0072\u0047\u0043\u0072\u0046\u006b\u002d\u0032\u0079\u0025\u0077\u002d\u0037\u0030\u0073\u0057\u006d\u004f\u0020\u004b\u0024\u0059\u0065\u004e\u005b\u0063\u007c\u004d\u005a\u0035\u0029\u0070\u0074\u0067\u0049\u005f\u005f\u0073\u0051\u0035\u006e\u0074\u006c\u0049\u0027\u0059\u0057\u0043\u0022\u0049\u006f\u0073\u0024\u002f\u005e\u0036\u003e\u0039\u0078\u0034\u0050\u005a\u0027\u0021\u0043\u0020\u0051\u003b\u004b\u0073\u0052\u0051\u0068\u0027\u004c\u006a\u0045\u007a\u0031\u0052\u0037\u004b\u0028\u006a\u0049\u0049\u0055\u0041\u005d\u0026\u0036\u0035\u004c\u0079\u0041\u0075\u006f\u007c\u0042\u0072\u002e\u004e\u0071\u006d\u004b\u0074\u0026\u004c\u0071\u002f\u004d\u004f\u003d\u0066\u0041\u003d\u006b\u0058\u0053\u004b\u0076\u0060\u0042\u0033\u003a\u004a\u002b\u0047\u0061\u004b\u0028\u0067\u0030\u0067\u007a\u005e\u0076\u0044\u0063\u0055\u0035\u005f\u0047\u0073\u0075\u006e\u0073\u006e\u0062\u002e\u003a\u0022\u004a\u0052\u0034\u003e\u0073\u0051\u002a\u0055\u002a\u0071\u0045\u0071\u0030\u003f\u0061\u0079\u0037\u0021\u003f\u007e\u005f\u0052\u005f\u0075\u0064\u0025\u002f\u0060\u0033\u007a\u0057\u006c\u0062\u006b\u0020\u0021\u0053\u005d\u0073\u005c\u006b\u0024\u002e\u003c\u006b\u0036\u0069\u0021\u006e\u0068\u007d\u0055\u004c\u006b\u0077\u0063\u0040\u0036\u0030\u0034\u007d\u0054\u0077\u0026\u002f\u003b\u0044\u006e\u003d\u0036\u0061\u003a\u007d\u0054\u0060\u0063\u006d\u0077\u002e\u0027\u006a\u0027\u007c\u0068\u0037\u004f\u0031\u0048\u005c\u0046\u007a\u0065\u0078\u002f\u0031\u0041\u0078\u004f\u0037\u007c\u0031\u003f\u0069\u0069\u0062\u004c\u005a\u005b\u007c\u0065\u004f\u0030\u0030\u003b\u007e\u0036\u005b\u0069\u0075\u0043\u005e\u005d\u006c\u0020\u0076\u0072\u003b\u0046\u0048\u003f\u004b\u0028\u002b\u0079\u0046\u0029\u0033\u0049\u0036\u0057\u003e\u0034\u0072\u003e\u005c\u0025\u006e\u0021\u006f\u006b\u0035\u0077\u003c\u0024\u0075\u0060\u006c\u0053\u0022\u004b\u0039\u004b\u0050\u0021\u0022\u0028\u0063\u0076\u0040\u002d\u0048\u0027\u0057\u0048\u0064\u003b\u0067\u0049\u007d\u0059\u0056\u0039\u0020\u0059\u0064\u006c\u005a\u003f\u0037\u002d\u0060\u002e\u0023\u0045\u003f\u0057\u0075\u0036\u0070\u006d\u0053\u007d\u0051\u0023\u0068\u0071\u002f\u0039\u0031\u0041\u0035\u0055\u0078\u0037\u0041\u0070\u007a\u004c\u0075\u0070\u0035\u0029\u005a\u0031\u005d\u0075\u0022\u0046\u0028\u0076\u003f\u0041\u0064\u0060\u0075\u007d\u0046\u002d\u004c\u0029\u0024\u0036\u005c\u0069\u0039\u0045\u004d\u005c\u0023\u006b\u006c\u004d\u0032\u006e\u0072\u0058\u0022\u0044\u0061\u007c\u0077\u005b\u0060\u0071\u0035\u0032\u0063\u0068\u0056\u0051\u0051\u002d\u005d\u006a\u0021\u003f\u0064\u0032\u006b\u0028\u002e\u005e\u0073\u0072\u0035\u005c\u003b\u0065\u0053\u0069\u005f\u0053\u0053\u002d\u002c\u0037\u0039\u006a\u0069\u007c\u005c\u004c\u0052\u0050\u004f\u003c\u0040\u002f\u0059\u0078\u0044\u002e\u0053\u0072\u005b\u0030\u005e\u007a\u0077\u005d\u0041\u004a\u0071\u0046\u0025\u006a\u0079\u0063\u0079\u0035\u0020\u0020\u0043\u0061\u004f\u003d\u002c\u0065\u0073\u0071\u003f\u0034\u004a\u0031\u002f\u002c\u006d\u0054\u003c\u0077\u002f\u005d\u007d\u0036\u0053\u006d\u0063\u0027\u004c\u004d\u002b\u0047\u005d\u007a\u0037\u0054\u0078\u0058\u0021\u002f\u0041\u002d\u0038\u005a\u0031\u005b\u0076\u0042\u0021\u002f\u006f\u005b\u0068\u0043\u0071\u002e\u0061\u0079\u0060\u0025\u0038\u0022\u0046\u003c\u0063\u003c\u003d\u005e\u003d\u005e\u0072\u002a\u007c\u0025\u0058\u0031\u004a\u0039\u0036\u002f\u003c\u005c\u007b\u0040\u0070\u0068\u0072\u005c\u0070\u0028\u0042\u007c\u0055\u0057\u0032\u002b\u004b\u0061\u0052\u0038\u0027\u003f\u0064\u0074\u0073\u0057\u004e\u0021\u0042\u003e\u0040\u0035\u0046\u0046\u0025\u003f\u004a\u005d\u0044\u0054\u003a\u0022\u0044\u0078\u0023\u0028\u0067\u0050\u0029\u0036\u0056\u0045\u004d\u004f\u0044\u0049\u007e\u002a\u0053\u0048\u0042\u0078\u0062\u0021\u006d\u0078\u002b\u003a\u0056\u002d\u0034\u0075\u0043\u003d\u0040\u003a\u0072\u0065\u0065\u006d\u0052\u0030\u0036\u006a\u007a\u0034\u0038\u0057\u0039\u0024\u0022\u0065\u0050\u005c\u0060\u005a\u005a\u003a\u0070\u0052\u0070\u002c\u007c\u002e\u003c\u0020\u006b\u003b\u0046\u0024\u0071\u0073\u0053\u0047\u0069\u004a\u0064\u0032\u002f\u0067\u0042\u005d\u0069\u002f\u0037\u0049\u0045\u0032\u0045\u0077\u0068\u0026\u005a\u0027\u0020\u0048\u004b\u002a\u0064\u003b\u0051\u007b\u0077\u007e\u0026\u007a\u007e\u006b\u002d\u002a\u005d\u002b\u007b\u006a\u0077\u0044\u0025\u0057\u0054\u006a\u0058\u006a\u006f\u0020\u006f\u0078\u0039\u004d\u004e\u007e\u0039\u004b\u005c\u0056\u007d\u0057\u0040\u0027\u002a\u0058\u0054\u0057\u007d\u002c\u0044\u0031\u005e\u007a\u0032\u0062\u0058\u002d\u0037\u0057\u0022\u0052\u007b\u0039\u0031\u0064\u0024\u0026\u002e\u0034\u0062\u007e\u0060\u0050\u006f\u0048\u0058\u0038\u0055\u0068\u0039\u003a\u0071\u004f\u0042\u0032\u0058\u0042\u004e\u0053\u0073\u003c\u005c\u005e\u006c\u006e\u0047\u0044\u0035\u004c\u0064\u0027\u005d\u0027\u003f\u003e\u0074\u0063\u0027\u007d\u0044\u004c\u0045\u003e\u0043\u002c\u005b\u0066\u006e\u0050\u0066\u004e\u0030\u0037\u002a\u0052\u0039\u007a\u003d\u0035\u003a\u007c\u004a\u0032\u003d\u0076\u0020\u002b\u0026\u0047\u0033\u0041\u004f\u0076\u0060\u0070\u0053\u0054\u003a\u004f\u0042\u0078\u0029\u006b\u0044\u0062\u0053\u0022\u002e\u0064\u0023\u0053\u0020\u0021\u005d\u0045\u0037\u0029\u002a\u0077\u007b\u0046\u0058\u0021\u006f\u0035\u006c\u0070\u004a\u0076\u0064\u007d\u0020\u0051\u003b\u0065\u005e\u0078\u0059\u006f\u0048\u003a\u0048\u0046\u0035\u0052\u0078\u0055\u0052\u0069\u004a\u0075\u0078\u002b\u0050\u0027\u007d\u0065\u004f\u005d\u0029\u0052\u007b\u0058\u0031\u005c\u0078\u003d\u007e\u0044\u0057\u004b\u0044\u0061\u004e\u0021\u005e\u005e\u007b\u0060\u004f\u0056\u007a\u003e\u0078\u005e\u0024\u0070\u0039\u0064\u0078\u0022\u0047\u004e\u0073\u0078\u0049\u006d\u0073\u0044\u007a\u0077\u0058\u0046\u005a\u0038\u005f\u0060\u0079\u0025\u0031\u006f\u0060\u004d\u002c\u007d\u0045\u0027\u005b\u006c\u003b\u006b\u0029\u006d\u005e\u0073\u005f\u003c\u004b\u0054\u005b\u004b\u002c\u0036\u0040\u0035\u007c\u003f\u007d\u0028\u004c\u0059\u0040\u0066\u003e\u0065\u0055\u0057\u0055\u004b\u0062\u004a\u0054\u0041\u0055\u007b\u0036\u0069\u0069\u0027\u007c\u0023\u0072\u0022\u0022\u0067\u0039\u0028\u006a\u0062\u0023\u0066\u007c\u002e\u0056\u0036\u003b\u0043\u0064\u0077\u0027\u002e\u0043\u007d\u006c\u0066\u0055\u0037\u0069\u003c\u0057\u0028\u0049\u003f\u005c\u005e\u0023\u007e\u0032\u0043\u0062\u0038\u0028\u0034\u0042\u007c\u0076\u002b\u0066\u0042\u0024\u0078\u0049\u006e\u0072\u0023\u0020\u003b\u006f\u0059\u002f\u007b\u0033\u0028\u0023\u0041\u0062\u0076\u003d\u005c\u005a\u003f\u0074\u0062\u007c\u004c\u0036\u0063\u0076\u003c\u0037\u0071\u004e\u0051\u0048\u0058\u002f\u0035\u0042\u0060\u004d\u0036\u004f\u0067\u0077\u0037\u0033\u0028\u0033\u005a\u0047\u006a\u0035\u0071\u0062\u004d\u0058\u0066\u0079\u005d\u0044\u003a\u006e\u0059\u004b\u005b\u005b\u0024\u0071\u0054\u0076\u0044\u0064\u007b\u0042\u005c\u005a\u004b\u0067\u007c\u002a\u0022\u0038\u004e\u005d\u007a\u002a\u002b\u002f\u0059\u0063\u005f\u0051\u0041\u0055\u0076\u0038\u0048\u007e\u005e\u002f\u002f\u0063\u0051\u0054\u006d\u0072\u0077\u0049\u0025\u0071\u002c\u006d\u006f\u007a\u005a\u007d\u0071\u004e\u0059\u0041\u002f\u0075\u0048\u0037\u003c\u005f\u0032\u0020\u0032\u0020\u0030\u0074\u0076\u0022\u0044\u0029\u005f\u0020\u0063\u0057\u0025\u0061\u0079\u005b\u007e\u004e\u005f\u0076\u0024\u0067\u0028\u0050\u002f\u0025\u002e\u0072\u002e\u0022\u006e\u005a\u005e\u003c\u002b\u0069\u0022\u0066\u0071\u0033\u006a\u0072\u005d\u005c\u0047\u004a\u007d\u0077\u002d\u0073\u0022\u007e\u005b\u0033\u004c\u0051\u0023\u0035\u006a\u004a\u007d\u0073\u004e\u0041\u0022\u005d\u0067\u005e\u0056\u003b\u003c\u0078\u0021\u002a\u0036\u0021\u0050\u0022\u0061\u0035\u007b\u0047\u0065\u0020\u0067\u0050\u0058\u007c\u0043\u0044\u0051\u0035\u0076\u0043\u004d\u002a\u007a\u0030\u0049\u0052\u007c\u0038\u0048\u004d\u0027\u0073\u006a\u005d\u0059\u0050\u007d\u0034\u0051\u0055\u0046\u004a\u002f\u0042\u002a\u004c\u0058\u003c\u004a\u0065\u0037\u0020\u0067\u007a\u0055\u0038\u003a\u0048\u002d\u0046\u0047\u0028\u002f\u0035\u0021\u0072\u002d\u0029\u0020\u0046\u004c\u006e\u0038\u0046\u0028\u006c\u002a\u0026\u0079\u0078\u0040\u006d\u004b\u0059\u0079\u0054\u007d\u003e\u0050\u002d\u005b\u005f\u0047\u005b\u0041\u0049\u004a\u007b\u003a\u0026\u007b\u006e\u002a\u0062\u0054\u006b\u003d\u0076\u0071\u002c\u006f\u004a\u0057\u006f\u0025\u005f\u0072\u006d\u006a\u0062\u0056\u0062\u002c\u002b\u005a\u005c\u0031\u0042\u005e\u0076\u0057\u007c\u0078\u0050\u003c\u0040\u0051\u0031\u0033\u0040\u0023\u004b\u0054\u0032\u0063\u005d\u004f\u002e\u0078\u003e\u0045\u0044\u0053\u004b\u0036\u0074\u0077\u0045\u0078\u006c\u0030\u0035\u005c\u0048\u006b\u003c\u007e\u006a\u0078\u0023\u0074\u007c\u007a\u006e\u0038\u0050\u005c\u007a\u002e\u0062\u0035\u0057\u003a\u006c\u0052\u0035\u003b\u0046\u007b\u006a\u002a\u004d\u0061\u0053\u0055\u0026\u007c\u0068\u0059\u003b\u0021\u0041\u0047\u0041\u0049\u0035\u0045\u0076\u0043\u0043\u0041\u0040\u0049\u006c\u002c\u0027\u005f\u0069\u005a\u0066\u0073\u0045\u0073\u0034\u0049\u003e\u0071\u0078\u0028\u0045\u0067\u0031\u0041\u007c\u0039\u0032\u0042\u0075\u0075\u003c\u0067\u0060\u004d\u0050\u0076\u0032\u005a\u0052\u007e\u0033\u004c\u005c\u0063\u0020\u004d\u0070\u0034\u0073\u003a\u0077\u006b\u0062\u005b\u0051\u0027\u0041\u0053\u0048\u005a\u0027\u0074\u0022\u006f\u002b\u002b\u0077\u0051\u002f\u007c\u0074\u0040\u006d\u0041\u0064\u004a\u004f\u002f\u0069\u0074\u002f\u0044\u0047\u0046\u0020\u007b\u004b\u0078\u007b\u0035\u002d\u0025\u0047\u0078\u003a\u0023\u002f\u0044\u0042\u0059\u0021\u0075\u0020\u0079\u0045\u006b\u003d\u006c\u0049\u0071\u006f\u003c\u003c\u006c\u003d\u007a\u0064\u0028\u0074\u0064\u0071\u004f\u0072\u004e\u0064\u006d\u0028\u006f\u004f\u0054\u0046\u0035\u0070\u0034\u0075\u004f\u0039\u0024\u0024\u004a\u0023\u0059\u0029\u0039\u003c\u003e\u006a\u007e\u0076\u0033\u006b\u006a\u0057\u0028\u0079\u005f\u002e\u0058\u0048\u0075\u0071\u0040\u0035\u0047\u0039\u0022\u0030\u0043\u0077\u002b\u0060\u0023\u004c\u003f\u006a\u003d\u0038\u005b\u0072\u0066\u005e\u006f\u0069\u0074\u0030\u0037\u0035\u0074\u0038\u0046\u0037\u0077\u0057\u007b\u0057\u007b\u003c\u0037\u0069\u0078\u0064\u0055\u0025\u004a\u0038\u006a\u0072\u003b\u0067\u0046\u005f\u0022\u003f\u003f\u0056\u003b\u004a\u0074\u0039\u0053\u0031\u0062\u002e\u0037\u0052\u0048\u0041\u007a\u0056\u0038\u006c\u0035\u0034\u0032\u002b\u0069\u004f\u006d\u004f\u0038\u0061\u0027\u0062\u007e\u0043\u005b\u0023\u0047\u0052\u0053\u0033\u0067\u004e\u004c\u003a\u0028\u0059\u0074\u006a\u0036\u0046\u004a\u0071\u004f\u004c\u0030\u0042\u007e\u006e\u0039\u006d\u0023\u0031\u0065\u0063\u005a\u0060\u0037\u007a\u002b\u0020\u0037\u003f\u003a\u005c\u0061\u0044\u003c\u0032\u0053\u004a\u0027\u0051\u0037\u0066\u0055\u0020\u0037\u0038\u003e\u0078\u005e\u0023\u0037\u0066\u0074\u004a\u007c\u0053\u005b\u0034\u0039\u0029\u0059\u0053\u0030\u0073\u005c\u002b\u004d\u005a\u0054\u0045\u0057\u006e\u0029\u003a\u003c\u0027\u003f\u0049\u0079\u0053\u0049\u0060\u004f\u0067\u006c\u0033\u0074\u0070\u006a\u0066\u003f\u0057\u002f\u003b\u003d\u0071\u0044\u0058\u0059\u0036\u0070\u002c\u0042\u0032\u0054\u0071\u004e\u007d\u004a\u0076\u0032\u002b\u004c\u0028\u003a\u006f\u0075\u007b\u0032\u004d\u0077\u0059\u0059\u0065\u0078\u0035\u003b\u0024\u003d\u005c\u0061\u002d\u005e\u002c\u0037\u0077\u002c\u0051\u0056\u0029\u0036\u003f\u0023\u006f\u0032\u0074\u0061\u0064\u003c\u0075\u0059\u0050\u003c\u005c\u0066\u005b\u005e\u0041\u002e\u003e\u005f\u003d\u0020\u0021\u004f\u0078\u0051\u003b\u007b\u006a\u0059\u0055\u0034\u0069\u0026\u0027\u0059\u0048\u004a\u0067\u0045\u0048\u0079\u0074\u0062\u0065\u003d\u002d\u007a\u006d\u0072\u002f\u007b\u004d\u003d\u0043\u0032\u0058\u002d\u0065\u003a\u003e\u004d\u0044\u0041\u0047\u0048\u0053\u002b\u0078\u006b\u0069\u0027\u007d\u0071\u0024\u0071\u0058\u0033\u0034\u0025\u007c\u0020\u006e\u005e\u0070\u003f\u0044\u0063\u0064\u0054\u003d\u007b\u0025\u0025\u0029\u002e\u004c\u004e\u003d\u006c\u0020\u005b\u0069\u0045\u0043\u0028\u0036\u003a\u0055\u003c\u002c\u002f\u007c\u0048\u0066\u0037\u004b\u0044\u003f\u0048\u0077\u0055\u007a\u002a\u0023\u0047\u0054\u006d\u0064\u0046\u0055\u007b\u005f\u0042\u0055\u0065\u006c\u0047\u0033\u005b\u0055\u007b\u003b\u004d\u0025\u002d\u005a\u003d\u005e\u0056\u003e\u002f\u007c\u0053\u0077\u007c\u0077\u007c\u007a\u007c\u006c\u006b\u0023\u004b\u0057\u0063\u0052\u004e\u004b\u007e\u0056\u0021\u0032\u002a\u0079\u0075\u005b\u0039\u003e\u0074\u003c\u003d\u002b\u007d\u004b\u0037\u0025\u0066\u007c\u0055\u005c\u006c\u0076\u005c\u002c\u0023\u003d\u0050\u0047\u002a\u004f\u003a\u0029\u0049\u0050\u0074\u003f\u006c\u0037\u006f\u0041\u003e\u0058\u007d\u0078\u0070\u0035\u0020\u0078\u007b\u0065\u0025\u004f\u0035\u0041\u005b\u0047\u003d\u006d\u0033\u0060\u0064\u007e\u0025\u0060\u0040\u0069\u0077\u0024\u006e\u003c\u0070\u0034\u0046\u004f\u0032\u003f\u007e\u0070\u005a\u0056\u0045\u0068\u0034\u0077\u0045\u0043\u0047\u0021\u0077\u0054\u0034\u0075\u0067\u0027\u0027\u0063\u0068\u004a\u0033\u0078\u007c\u0058\u005b\u0072\u003e\u0059\u0044\u0077\u006d\u005b\u003e\u007b\u005b\u0029\u0031\u0035\u0067\u004c\u0052\u003a\u0069\u007e\u002a\u006f\u007c\u0022\u0026\u0028\u0029\u003f\u0031\u003c\u006c\u0070\u0073\u0025\u0054\u0064\u0022\u002d\u006c\u0053\u0054\u0078\u006a\u002b\u005a\u0062\u0054\u0072\u007e\u0053\u005b\u0076\u0033\u0079\u007e\u004a\u0073\u005c\u0031\u005b\u003d\u003a\u004c\u0058\u007d\u005f\u0040\u0028\u003a\u0054\u0026\u0027\u0058\u0046\u004c\u004f\u0073\u0037\u0071\u004c\u0040\u005c\u007c\u006a\u0052\u0065\u0057\u0026\u0043\u0043\u003c\u0051\u0066\u0042\u0066\u0026\u0045\u0036\u0022\u005d\u0052\u002e\u0044\u0050\u002f\u0071\u0037\u005d\u0052\u0032\u003e\u0079\u0061\u006b\u0035\u006c\u0060\u0078\u0044\u0051\u0034\u005b\u0076\u007c\u0058\u0068\u0053\u0030\u0069\u0054\u005e\u0040\u0021\u0034\u0059\u0025\u0025\u005b\u0036\u0054\u0025\u0074\u003d\u0032\u0053\u003f\u004c\u0077\u003c\u005b\u002d\u0037\u0058\u0064\u0028\u0020\u0028\u0029\u0062\u007e\u0026\u0033\u0066\u007a\u0033\u0062\u0061\u0072\u0026\u005b\u0056\u0043\u0062\u0032\u007d\u0068\u002a\u004c\u0065\u0023\u006c\u0027\u0062\u0054\u007c\u0024\u0037\u0022\u002e\u0056\u0067\u003e\u0061\u0066\u0064\u0066\u0034\u0042\u006d\u0050\u007c\u0078\u0024\u003b\u004d\u0039\u0062\u0064\u0021\u003e\u002a\u0050\u003b\u0066\u0062\u0069\u0040\u005b\u0079\u0035\u003e\u0051\u002f\u0041\u0060\u0038\u0049\u0028\u0046\u0041\u0045\u0055\u0057\u0037\u0069\u006f\u0049\u005c\u005a\u0061\u004d\u0036\u003f\u0054\u0027\u0079\u0078\u0067\u0038\u0021\u004c\u006f\u007c\u0054\u0021\u0071\u0033\u0033\u0023\u005b\u003a\u0041\u0076\u0053\u0058\u0079\u0063\u0034\u004c\u004c\u0070\u007d\u0035\u005a\u0063\u006e\u0053\u0035\u0069\u0034\u0033\u004b\u0075\u003e\u004c\u0069\u004d\u0022\u0028\u0046\u002a\u0030\u0060\u0052\u004f\u003a\u0020\u0079\u0047\u005a\u0068\u0041\u0056\u007a\u0057\u004f\u0050\u0028\u0034\u0054\u0060\u0025\u002c\u0076\u0039\u003a\u007b\u007a\u0023\u002a\u0026\u002e\u0071\u0060\u007c\u0068\u003e\u0050\u004d\u0071\u0026\u005b\u0051\u0025\u0020\u0021\u006f\u0063\u0021\u003e\u0055\u0074\u0026\u004f\u0043\u005d\u0072\u0033\u0030\u002d\u002d\u007a\u0068\u0077\u0041\u0032\u0041\u004f\u0072\u0066\u0032\u0043\u002c\u0020\u002c\u002a\u004e\u0063\u0033\u0075\u0035\u0031\u003a\u002d\u004b\u0074\u0048\u0063\u0037\u004a\u0035\u004e\u0057\u0068\u0062\u0079\u0047\u0059\u002f\u0041\u002b\u0040\u0072\u006e\u0061\u0079\u0061\u006f\u004a\u0066\u002e\u0072\u0054\u0066\u006e\u0065\u0036\u0054\u0039\u0064\u0068\u002c\u0073\u0038\u0021\u0042\u0030\u0021\u0063\u0024\u002d\u007a\u003f\u007e\u0059\u0033\u0030\u0057\u0044\u0070\u003d\u0054\u0052\u0055\u0063\u0046\u0072\u007a\u0043\u0064\u0050\u006a\u0064\u0046\u0051\u0065\u003a\u0020\u0023\u0062\u006b\u0074\u0070\u0042\u0033\u0072\u006c\u0048\u0038\u0072\u0058\u0053\u0048\u0041\u0069\u002a\u0034\u004c\u0025\u002a\u0069\u0020\u0022\u0022\u002f\u0054\u006d\u007c\u005d\u0039\u002e\u004a\u0065\u0077\u0063\u0042\u0064\u003a\u0065\u0024\u0028\u0065\u006c\u006f\u0041\u0035\u0060\u0021\u006a\u003c\u0024\u0031\u0049\u004d\u0040\u006b\u0054\u0065\u0050\u0069\u006d\u0020\u005b\u0037\u005b\u0058\u0073\u0064\u007d\u002e\u0050\u006e\u006f\u0075\u0040\u003d\u0037\u0020\u002a\u007a\u003e\u004c\u0078\u0048\u006b\u0079\u0032\u006f\u004f\u005b\u0052\u0073\u003a\u0053\u0051\u005f\u0067\u004b\u0053\u0028\u0023\u007e\u006a\u006b\u007b\u007d\u007c\u007e\u0046\u0030\u007b\u0044\u003b\u006f\u0078\u0032\u0062\u0035\u002f\u003a\u0021\u0055\u004f\u0030\u004b\u007b\u0034\u0045\u006e\u0021\u004e\u005b\u002e\u0021\u0024\u004f\u0024\u0054\u005c\u004c\u0046\u0079\u0055\u007c\u0020\u004a\u0030\u0059\u002c\u002c\u0064\u0039\u0022\u007b\u0073\u002a\u0036\u002c\u0031\u007d\u0067\u0066\u007e\u0051\u007d\u0066\u0075\u0039\u004d\u0024\u0073\u006b\u002a\u0057\u007c\u0048\u007b\u006d\u0062\u0061\u007e\u0066\u0068\u0034\u0051\u004f\u0055\u006c\u007d\u007e\u007e\u0044\u003f\u0023\u0047\u0053\u0074\u0022\u006b\u003d\u004a\u007e\u007d\u0047\u0049\u003e\u003c\u005c\u0078\u0063\u0046\u002c\u005d\u0046\u002e\u0042\u005c\u004f\u0057\u0072\u0036\u006c\u0038\u002e\u004f\u0030\u005d\u0055\u006b\u003a\u006f\u0050\u006b\u005a\u0043\u006e\u0027\u0029\u0030\u0039\u005d\u0024\u003f\u0060\u005c\u0025\u007a\u007b\u0072\u006c\u0067\u0070\u0066\u0063\u004c\u0066\u006d\u0061\u005c\u0070\u0040\u0044\u003b\u005f\u006d\u002b\u0044\u0021\u0029\u005a\u0066\u0057\u0026\u007d\u0052\u0078\u0055\u002b\u0071\u006a\u0040\u004e\u0043\u0050\u007b\u0051\u004e\u0063\u0069\u004f\u0051\u0076\u0054\u006b\u006e\u0078\u0071\u0042\u0032\u0064\u005d\u0030\u006d\u0032\u0060\u0043\u0034\u0048\u0062\u007e\u002c\u0067\u0064\u003f\u007d\u0053\u0052\u0061\u003c\u004d\u0029\u0055\u004f\u006d\u007d\u006f\u0053\u002c\u0036\u0051\u0065\u006c\u0049\u006a\u007e\u0049\u0061\u0046\u0051\u004c\u0036\u0020\u0023\u0034\u0036\u0050\u0044\u007e\u0073\u0031\u0051\u0059\u0065\u0025\u0036\u0035\u004a\u0043\u0061\u0033\u0054\u0061\u006c\u003b\u006d\u0028\u0040\u0041\u0027\u0031\u0031\u005c\u002e\u006c\u007c\u002f\u005c\u0038\u007c\u0077\u0024\u0069\u0060\u0063\u005f\u006d\u0071\u0049\u0057\u006d\u0041\u0065\u0046\u0063\u004c\u003a\u0067\u0055\u0042\u0042\u007d\u002d\u0043\u0031\u007d\u0074\u005a\u006c\u004f\u0045\u003c\u0048\u0048\u003a\u0065\u0068\u006d\u0023\u0035\u0041\u002b\u0052\u0044\u002b\u003b\u007a\u0064\u0031\u005a\u007b\u003f\u006d\u0033\u0039\u0027\u0042\u0042\u0054\u005d\u0073\u0030\u006c\u007a\u007b\u0040\u0053\u0031\u0041\u006e\u005d\u006b\u0069\u0046\u0033\u007d\u0050\u006c\u003a\u0076\u0040\u0059\u002b\u0038\u0030\u0038\u007d\u006e\u006b\u003f\u0061\u0079\u0052\u0069\u0060\u0060\u005a\u002a\u0027\u0033\u0034\u0071\u002f\u0041\u005e\u003c\u0075\u007a\u004a\u003e\u0065\u0031\u005f\u0071\u002b\u004b\u0027\u0056\u004a\u0067\u0063\u0055\u0049\u004e\u003c\u0070\u0053\u0046\u0022\u0024\u0034\u0022\u003e\u0053\u0025\u0049\u0034\u006e\u0061\u0074\u0042\u007a\u004a\u0056\u0071\u002f\u0057\u0059\u0074\u0054\u0068\u0048\u0028\u002b\u003f\u0034\u003e\u003d\u0074\u007a\u0021\u006a\u003e\u0064\u0022\u005b\u0079\u0050\u006c\u005b\u005a\u0036\u003d\u007b\u005d\u002a\u005b\u0079\u0025\u0066\u005f\u0054\u0042\u006f\u0041\u0037\u0036\u005c\u002f\u0068\u007d\u0024\u002a\u006e\u007e\u0054\u004e\u0028\u0042\u0074\u003b\u004f\u003d\u0077\u0056\u002d\u0037\u0058\u004b\u0073\u005e\u006c\u0048\u0070\u002c\u0041\u0064\u0064\u006d\u0041\u0045\u002a\u003d\u0027\u005e\u0032\u0063\u006d\u0058\u003c\u0074\u0020\u0054\u0039\u0064\u0050\u004a\u0023\u0069\u004a\u005f\u004e\u0065\u003f\u0036\u0046\u007a\u005c\u0066\u0022\u0068\u0048\u007d\u0021\u007c\u0058\u0023\u005f\u002e\u006c\u006d\u0073\u0064\u006d\u0060\u0058\u0065\u0054\u0063\u003b\u0046\u0063\u0066\u006d\u0062\u004d\u0050\u003c\u0037\u002d\u007b\u0061\u0068\u0052\u0054\u0058\u0035\u006a\u007d\u0074\u0066\u0074\u0044\u0036\u0031\u0045\u0064\u0036\u0038\u0048\u0061\u0052\u0062\u0074\u0051\u0049\u0036\u002f\u0037\u002a\u002c\u0027\u0032\u0064\u003b\u0027\u0060\u002a\u0040\u0049\u0026\u0056\u0024\u0037\u0071\u0055\u007e\u002c\u0073\u003d\u004a\u0040\u003d\u0042\u0079\u0060\u0046\u003c\u0032\u0021\u0025\u0045\u005f\u0059\u0055\u005b\u0067\u0069\u0047\u004e\u0075\u0078\u007e\u0022\u0047\u002f\u0061\u0070\u0071\u0041\u0048\u004b\u0037\u004d\u0051\u0063\u0034\u0067\u0067\u0070\u0061\u0021\u007a\u0030\u0051\u007d\u005b\u0078\u0058\u004d\u0023\u0028\u002b\u0059\u006b\u006c\u003e\u0066\u006b\u0049\u004b\u0066\u0025\u0061\u0060\u004f\u003c\u0040\u0059\u006a\u007e\u0044\u0039\u007b\u0076\u0027